{"summary": "{
  "paper_title": "On Merging Feature Engineering and Deep Learning for Diagnosis, Risk Prediction",
  "authors": ["Zvuloni et al."],
  "abstract": "We developed a unified model pipeline and trained it for three different and independent cardio-related tasks, utilizing both feature engineering and deep learning approaches as well as combining both. Experiments were conducted using a large dataset of over 2.3M 12-lead ECG recordings. For all tasks, cardiac arrhythmia diagnosis, atrial fibrillation risk prediction, and age estimation, the DL model reached similar or higher performance than the FE approach.",
  "results": {
    "arrhythmia_diagnosis": {
      "FE_performance": "comparable",
      "DL_performance": "similar"
    },
    "atrial_fibrillation_risk_prediction": {
      "FE_performance": "comparable",
      "DL_performance": "higher"
    },
    "age_estimation": {
      "FE_performance": "lower",
      "DL_performance": "higher"
    }
  },
  "conclusion": "We explain this finding by the fact that age estimation is not a classical clinical task that the 12-lead ECG was historically used for. Consequently, FE encompassing domain knowledge for this specific task was low.",
  "acknowledgment": {
    "thanks_to": ["S. Biton", "S. Gendelman"],
    "fellowship": "The Miriam and Aaron Gutwirth Memorial Fellowship"
  }
}", "dataset_name": "CODE-15%: a large scale annotated dataset of 12-lead ECGs", "source_length": 53716, "full_source_length": 49051, "num_context_blocks": 1}

